INSERT INTO `topic` VALUES (1,'2025-08-17 15:50:44.000000','안 읽씹이 더 낫다','읽씹이 더 낫다','안 읽씹 vs 읽씹 뭐가 더 낫나?'),(2,'2025-08-17 15:50:44.000000','윈터','카리나','카리나 vs 윈터 당신의 원픽은?'),(3,'2025-08-17 15:50:44.000000','단검','야구방망이','강도를 만났을 때, 무엇으로 막는다면?'),(4,'2025-08-17 15:50:44.000000','월요일 휴무','금요일 휴무','일주일에 하루 쉴 수 있다면?'),(5,'2025-08-15 05:21:24.000000','짜장면','짬뽕','죽기 전 마지막 식사로 짜장면 vs 짬뽕'),(6,'2025-08-15 05:21:24.000000','스마트폰 없이','친구 없이','1년 동안 스마트폰 없이 살기 vs 1년 동안 친구 없이 살기'),(7,'2025-08-15 05:21:24.000000','카리나 vs 윈터, 당신의 원픽은?','카리나','윈터'),(8,'2025-08-15 05:21:24.000000','초등학생으로','10년 후 미래로','다시 초등학생으로 돌아가기 vs 10년 후 미래로 가기'),(9,'2025-08-15 05:21:24.000000','100억','사랑','100억 받기 vs 평생 사랑 받기'),(10,'2025-08-15 05:21:24.000000','잠 안 오기','배고픔 느끼기','평생 잠 안 오기 vs 평생 배고픔 느끼기'),(11,'2025-08-15 05:21:24.000000','1시간 인터넷','1끼 식사','하루에 1시간만 인터넷 가능 vs 하루에 1끼만 먹기'),(12,'2025-08-15 05:21:24.000000','백수','월 100만 원 직장','평생 백수로 살기 vs 평생 월 100만원 벌기'),(13,'2025-08-15 05:21:24.000000','강아지','고양이','다음 생에 강아지로 태어나기 vs 고양이로 태어나기'),(14,'2025-08-15 05:21:24.000000','항상 솔직함','항상 거짓말','항상 솔직하게 말하기 vs 항상 거짓말하기'),(15,'2025-08-15 05:21:24.000000','항상 더움','항상 추움','항상 덥게 살기 vs 항상 춥게 살기'),(16,'2025-08-15 05:21:24.000000','죽음 알기','죽음 모르기','1분 뒤 죽는다는 걸 알고 살기 vs 죽는 날 모르고 살기'),(17,'2025-08-15 05:21:24.000000','10년 감옥 + 100억','지금 1억','10년 감옥살이 후 100억 vs 지금 당장 1억'),(18,'2025-08-15 05:21:24.000000','과거로 이동','미래로 이동','지금에서 어린 시절로 돌아가기 vs 20년 후로 순간이동'),(19,'2025-08-15 05:21:24.000000','읽기만 가능','말하기만 가능','읽을 수는 있지만 말 못하기 vs 말할 수는 있지만 못 읽기'),(20,'2025-08-15 05:21:24.000000','영원한 여름','영원한 겨울','한 계절만 살아야 한다면 여름 vs 겨울'),(21,'2025-08-15 05:21:24.000000','아무도 나 기억 못함','내가 아무도 기억 못함','아무도 나를 기억하지 못함 vs 내가 아무도 기억 못 함'),(22,'2025-08-15 05:21:24.000000','항상 느림','항상 배고픔','항상 느리게 살기 vs 항상 배고프게 살기'),(23,'2025-08-15 05:21:24.000000','미래 예측','과거 완벽 기억','미래를 예측할 수 있음 vs 과거를 완벽히 기억할 수 있음');
